struct Party { long id; std::string name; virtual ~Party() = default; };
struct Person : Party { std::string birth_date; };

// one join per concrete type; the key travels along the path
Person load_person(pqxx::work& tx, long id) {
  auto r = tx.exec("SELECT p.id, p.name, e.birth_date "
                   "FROM party p JOIN person e ON e.id = p.id "
                   "WHERE p.id = $1", pqxx::params{id}).one_row();
  return Person{{r[0].as<long>(), r[1].as<std::string>()}, r[2].as<std::string>()};
}
